const LORE=[['People',[
['Imane Kryv','Pilgrim Hero','Descendant of the Kryv family and of Deona Kryv, one of the Pilgrims’ original founders. A contrarian who left the inner worlds to chase Endless relics with eccentric adventurers, and experimented with cybernetic augmentation. Her first contact with the Umbral Choir is the start of the storyline, told partly in her own voice.',['1a','2','3a','3b']],
['Belzah Rach','An Endless','Described as having “a brilliant mind, full of ideas and compassion, and history”. A cadre of echoes seeks his aid to shatter the Choir, and he later helps ready it for individuality. In the Militarist ending he disappears again.',['3a','4a','4b']],
['Solmire Prima','Orchestrator','The Choir’s orchestrator, who needs military might to quash internal uprisings.',['3a']],
['Sila Minor','Hero','An echo that was seared by Dust trapped in a dead Lost’s husk, then watched Isyander and his Academy from the shattered Harrow system. The Academy gave it license to roam.',[]],
['Fasol Staccato','Hero','Broke from the Choir inside a Craver warship, where stolen Dust made it a cognitive powerhouse. It converted the crew to pacifism.',[]],
['Lare Fermata','Hero','An aggressive refrain that infiltrated other species’ systems. It was freed after destroying a Hissho Kestrel-class vessel, and is linked to the Rydha Skirmish with Horatio fleets.',[]],
['Miredo Sharp','Hero','Lost a battle of wits with the Sophon AI ENFER at Hekim, which then freed it from the gestalt with a controlled Dust exposure.',[]]]],
['The Umbral Choir',[
['Over-gestalt and echoes','Choir terms','The Choir is a single mind that shattered into “echoes” that rush toward the Endless galaxy’s cry of anguish. The storyline asks whether it should reunify (Militarist), become many (Pacifist) or watch from afar (Scientist).',['3a','4a','4b','4c']],
['Nexus','Hidden fortress','The Choir’s single hidden system, built of interlocking rings, because as immaterial wraiths it cannot colonize worlds the usual way. In a catastrophe it can transmigrate Nexus to another system.',[]],
['Sanctuaries','Colonies of the Choir','Used to inhabit or take control of Systems, and to watch other lifeforms more closely.',['2','1a']],
['Sleepers and Backdoors','Hacking outcomes','Both are possible outcomes of a hack against a system owned by another empire. A Sleeper is embedded in a system’s people; Backdoors raise hacking speed and cost Bandwidth upkeep.',['3b','4d']],
['Cloaked fleets','Stealth','A Cloaking module on one ship plus the “Cloak” fleet action hides a fleet. Needed for the Freedom choice.',['3a']]]]];
function lore(){$('#t-lore').innerHTML=LORE.map(g=>'<h2 class="sec">'+g[0]+'</h2><div class="cols">'+g[1].map(i=>'<div class="card"><h3>'+i[0]+'</h3><div class="tag">'+i[1]+'</div><p>'+i[2]+'</p>'+ch(...i[3])+'</div>').join('')+'</div>').join('')}
function rewards(){let h='<div class="note">'+esc(DK.DLCUCTitle)+': '+pretty(DK.DLCUCDescription)+'</div>';
const card2=(b)=>'<div class="card"><h3>'+esc(DK[b+'Title'])+'</h3>'+(DK[b+'ShortTitle']?'<div class="tag">'+esc(DK[b+'ShortTitle'])+'</div>':'')+(DK[b+'Description']?'<p>'+pretty(DK[b+'Description'])+'</p>':'')+(DK[b+'Effect']?'<div class="eff">'+pretty(DK[b+'Effect'])+'</div>':'')+'</div>';
h+='<div class="note">The file does not say which chapter or choice grants these, so no source is guessed.</div>';
h+='<h2 class="sec">Laws</h2><div class="cols">'+['01','02','03','04'].map(n=>card2('LawP00QuestUC'+n)).join('')+'</div>';
h+='<h2 class="sec">Technology</h2><div class="cols">'+card2('TechnologyDefinitionQuestUC01')+'</div>';
h+='<h2 class="sec">Unique planet</h2><div class="cols">'+card2('UniquePlanetUmbralChoir')+'</div>';
$('#t-rewards').innerHTML=h}
const TB=[['map','Quest map'],['lore','Lore'],['rewards','Rewards'],['overview','Overview'],['browse','Browse by topic'],['raw','All strings']];
$('#tabs').innerHTML=TB.map(t=>'<a href="#'+t[0]+'" data-t="'+t[0]+'">'+t[1]+'</a>').join('');
function tab(t){TB.forEach(x=>$('#t-'+x[0]).hidden=x[0]!==t);document.querySelectorAll('#tabs a').forEach(a=>a.classList.toggle('on',a.dataset.t===t))}
function route(){const h=location.hash.slice(1);
if(h.startsWith('n-')&&NM[h.slice(2)]){tab('map');show(h.slice(2))}
else if(h.startsWith('c-')&&C[+h.slice(2)]){tab('browse');showCat(+h.slice(2));window.scrollTo(0,0)}
else if(h==='browse'){tab('browse');showCat(cur)}
else if(TB.some(t=>t[0]===h))tab(h);else{tab('map');if(!$('.nd.sel'))show('1a')}}
buildMap();lore();rewards();overview();raw();addEventListener('hashchange',route);route();
